USE [JamunaBankProcurement];
GO
CREATE OR ALTER PROCEDURE dbo.usp_Comment_Add @RequisitionId BIGINT,@ReqItemId BIGINT=NULL,@CommentType VARCHAR(30),@CommentText NVARCHAR(4000),@ActorEmployeeId VARCHAR(30)
AS BEGIN SET NOCOUNT ON;IF NOT EXISTS(SELECT 1 FROM dbo.REQUISITION_HEADER WHERE REQUISITION_ID=@RequisitionId AND IS_ACTIVE=1)BEGIN SELECT'002'RESULT_CODE,N'Requisition not found.'RESULT_MESSAGE,NULL ENTITY_ID,NULL REFERENCE_NO;RETURN;END;IF @ReqItemId IS NOT NULL AND NOT EXISTS(SELECT 1 FROM dbo.REQUISITION_ITEM WHERE REQ_ITEM_ID=@ReqItemId AND REQUISITION_ID=@RequisitionId AND IS_ACTIVE=1)BEGIN SELECT'001'RESULT_CODE,N'Requisition item does not belong to the requisition.'RESULT_MESSAGE,NULL ENTITY_ID,NULL REFERENCE_NO;RETURN;END;IF NULLIF(LTRIM(RTRIM(@CommentType)),'')IS NULL OR NULLIF(LTRIM(RTRIM(@CommentText)),'')IS NULL BEGIN SELECT'001'RESULT_CODE,N'Comment type and text are required.'RESULT_MESSAGE,NULL ENTITY_ID,NULL REFERENCE_NO;RETURN;END;INSERT dbo.COMMENT_NOTE(REQUISITION_ID,REQ_ITEM_ID,COMMENT_TYPE,COMMENT_TEXT,CREATED_BY_EMPLOYEE_ID)VALUES(@RequisitionId,@ReqItemId,UPPER(LTRIM(RTRIM(@CommentType))),LTRIM(RTRIM(@CommentText)),@ActorEmployeeId);SELECT'000'RESULT_CODE,N'Success'RESULT_MESSAGE,CONVERT(BIGINT,SCOPE_IDENTITY())ENTITY_ID,NULL REFERENCE_NO;END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_History_GetApproval @RequisitionId BIGINT AS BEGIN SET NOCOUNT ON;SELECT APPROVAL_ID,REQUISITION_ID,REQ_ITEM_ID,ACTION_TYPE,ACTION_BY_EMPLOYEE_ID,ACTION_ROLE,FROM_STAGE,TO_STAGE,ACTION_DATETIME,REMARKS,BATCH_REFERENCE_ID FROM dbo.APPROVAL_ACTION WHERE REQUISITION_ID=@RequisitionId ORDER BY ACTION_DATETIME,APPROVAL_ID;END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_History_GetWorkflow @RequisitionId BIGINT AS BEGIN SET NOCOUNT ON;SELECT WORKFLOW_HISTORY_ID,REQUISITION_ID,WORKFLOW_RULE_ID,FROM_STAGE,TO_STAGE,ACTION_TYPE,ACTION_BY_EMPLOYEE_ID,ACTION_DATETIME,REMARKS,BATCH_REFERENCE_ID FROM dbo.WORKFLOW_HISTORY WHERE REQUISITION_ID=@RequisitionId ORDER BY ACTION_DATETIME,WORKFLOW_HISTORY_ID;END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_History_GetProcurementStatus @RequisitionId BIGINT AS BEGIN SET NOCOUNT ON;SELECT h.STATUS_HISTORY_ID,p.REQUISITION_ID,s.STATUS_CODE,s.STATUS_NAME,h.STATUS_DATE,h.REFERENCE_NO,h.CHANGED_BY_EMPLOYEE_ID,h.REMARKS,h.BATCH_REFERENCE_ID FROM dbo.PROCUREMENT_STATUS_HISTORY h JOIN dbo.PROCUREMENT_TRACKING p ON p.PROCUREMENT_ID=h.PROCUREMENT_ID JOIN dbo.PROCUREMENT_STATUS_MASTER s ON s.STATUS_ID=h.STATUS_ID WHERE p.REQUISITION_ID=@RequisitionId ORDER BY h.STATUS_DATE,h.STATUS_HISTORY_ID;END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_AuditLog_Search @EntityName VARCHAR(100)=NULL,@EntityId BIGINT=NULL,@PageNumber INT=1,@PageSize INT=50 AS BEGIN SET NOCOUNT ON;IF @PageNumber<1 SET @PageNumber=1;IF @PageSize<1 OR @PageSize>200 SET @PageSize=50;SELECT AUDIT_ID,ENTITY_NAME,ENTITY_ID,ACTION_TYPE,OLD_VALUE_JSON,NEW_VALUE_JSON,ACTION_BY_EMPLOYEE_ID,ACTION_DATETIME,IP_ADDRESS,CORRELATION_ID FROM dbo.AUDIT_LOG WHERE(@EntityName IS NULL OR ENTITY_NAME=@EntityName)AND(@EntityId IS NULL OR ENTITY_ID=@EntityId)ORDER BY ACTION_DATETIME DESC,AUDIT_ID DESC OFFSET(@PageNumber-1)*@PageSize ROWS FETCH NEXT @PageSize ROWS ONLY;END;
GO
GRANT EXECUTE ON dbo.usp_History_GetApproval TO procurement_app_executor;GRANT EXECUTE ON dbo.usp_History_GetWorkflow TO procurement_app_executor;GRANT EXECUTE ON dbo.usp_History_GetProcurementStatus TO procurement_app_executor;GRANT EXECUTE ON dbo.usp_AuditLog_Search TO procurement_app_executor;
GO
